import { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';

function Dashboard() {
  const navigate = useNavigate();
  const [userData, setUserData] = useState({ name: 'Пользователь' });

  useEffect(() => {
    const token = localStorage.getItem('authToken');

    const fetchUserData = async () => {
      try {
        const response = await fetch('http://127.0.0.1:8000/api/user', {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${token}`,
            'Accept': 'application/json',
          },
          credentials: 'include' // Важно для Sanctum
        });

        console.log('API Response:', response);

        // Проверяем статус ответа перед проверкой content-type
        if (response.status === 401) {
          throw new Error('Unauthorized');
        }

        const contentType = response.headers.get('content-type');
        if (!contentType || !contentType.includes('application/json')) {
          throw new Error('Invalid content type');
        }

        const data = await response.json();

        // Проверяем, что данные содержат имя пользователя
        if (!data.name && data.user?.name) {
          setUserData(data.user);
        } else if (data.name) {
          setUserData(data);
        } else {
          throw new Error('User data is incomplete');
        }
      } catch (error) {
        console.error('Fetch error:', error);
        localStorage.removeItem('authToken');
        // Используем navigate вместо window.location для SPA-перехода
        navigate('/login', { replace: true });
      }
    };

    if (token) {
      fetchUserData();
    } else {
      navigate('/login', { replace: true });
    }
  }, [navigate]);

  const handleLogout = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        navigate('/login', { replace: true });
        return;
      }

      const response = await fetch('http://127.0.0.1:8000/api/logout', {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json',
          'Content-Type': 'application/json',
        },
        credentials: 'include' // Важно для Sanctum
      });

      if (!response.ok) {
        throw new Error('Logout failed');
      }
    } catch (error) {
      console.error('Ошибка выхода:', error);
    } finally {
      localStorage.removeItem('authToken');
      navigate('/login', { replace: true });
    }
  };

  return (
    <div className='dashboard-container'>
      <div className='dashboard-header'>
        <h1 className='dashboard-title'>Личный кабинет</h1>
        <p className='dashboard-welcome'>Добро пожаловать, {userData.name}!</p>
      </div>

      <div className='dashboard-content'>
        <div className='dashboard-actions'>
          <Link to='/catalog' className='shop-link'>
            <span>За покупками</span>
            <svg
              xmlns='http://www.w3.org/2000/svg'
              width='24'
              height='24'
              viewBox='0 0 24 24'
              fill='none'
              stroke='currentColor'
              strokeWidth='2'
              strokeLinecap='round'
              strokeLinejoin='round'
            >
              <path d='M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z'></path>
              <line x1='3' y1='6' x2='21' y2='6'></line>
              <path d='M16 10a4 4 0 0 1-8 0'></path>
            </svg>
          </Link>

          <button onClick={handleLogout} className='logout-button'>
            <span>Выйти</span>
            <svg
              xmlns='http://www.w3.org/2000/svg'
              width='24'
              height='24'
              viewBox='0 0 24 24'
              fill='none'
              stroke='currentColor'
              strokeWidth='2'
              strokeLinecap='round'
              strokeLinejoin='round'
            >
              <path d='M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4'></path>
              <polyline points='16 17 21 12 16 7'></polyline>
              <line x1='21' y1='12' x2='9' y2='12'></line>
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
